using UnityEngine;

namespace ColorGateBlast
{
    /// <summary>
    /// A single campaign level stored as an asset. The plain-data <see cref="LevelDefinition"/> is what the
    /// game rules and the Editor solver operate on. Assets are generated by
    /// Tools &gt; Color Gate Blast &gt; Generate Starter Levels 1-10 and loaded from Resources/Levels.
    /// </summary>
    [CreateAssetMenu(fileName = "Level_001", menuName = "Color Gate Blast/Level Data")]
    public sealed class LevelData : ScriptableObject
    {
        public LevelDefinition definition = new LevelDefinition();

        public int LevelNumber { get { return definition.levelNumber; } }
    }
}
